{"roles":{"stucco":["white_concrete"],"structure":["dark_oak_log","dark_oak_fence"],"header":["dark_oak_planks"],"fascia":["dark_oak_slab"],"base_paving":["smooth_stone","smooth_stone_slab"],"roof_deck":["smooth_stone_slab"],"driveway_joints":["light_gray_concrete"],"ledgestone":["mud_bricks","packed_mud","mud_brick_slab"],"glass":["glass_pane"],"front_door":["acacia_door"],"utility_door":["dark_oak_door"],"accent":["orange_concrete"],"pool":["water","light_blue_concrete","smooth_quartz_slab","smooth_quartz_stairs"],"pit_floor":["smooth_quartz","smooth_quartz_stairs"],"ground":["sand","gravel","grass_block","dirt"],"floor_public":["smooth_stone","light_gray_concrete","white_concrete"],"floor_bedrooms":["spruce_planks"],"floor_baths":["smooth_quartz"],"ceiling":["spruce_planks"],"wall_panelling":["spruce_trapdoor","spruce_stairs","spruce_slab","spruce_planks","spruce_fence"],"partitions":["white_concrete"],"fireplace":["mud_bricks","black_concrete","campfire","smooth_stone_slab"],"car":["cyan_concrete","white_concrete","black_concrete","iron_block","iron_trapdoor","glass_pane","sea_lantern"],"planting":["cactus","jungle_log","jungle_leaves","dead_bush","short_grass","large_fern"],"entry_lighting":["lantern"],"mailbox":["mud_bricks","mud_brick_slab","black_concrete"],"poolside_furniture":["smooth_quartz_stairs","smooth_quartz_slab","birch_slab"],"street":["gray_concrete"]},"objects":["cyan_concrete","yellow_concrete","red_concrete","iron_block","black_concrete","cactus","jungle_log","jungle_leaves","large_fern","potted_cactus","dead_bush","short_grass","lantern","sea_lantern","end_rod","daylight_detector","dark_oak_fence","orange_carpet","white_carpet","cyan_carpet","yellow_carpet","smooth_red_sandstone_stairs","quartz_stairs","quartz_slab","smooth_quartz_stairs","birch_planks","birch_slab","birch_stairs","birch_trapdoor","iron_trapdoor","spruce_fence","spruce_slab","spruce_stairs","spruce_trapdoor","lectern","bookshelf","flower_pot","item_frame","barrel","smoker","furnace","cauldron","orange_bed","cyan_bed","yellow_bed","light_blue_bed","white_bed","acacia_door","white_concrete","glass_pane","mud_bricks","mud_brick_slab","smooth_stone_slab","water","light_blue_concrete","smooth_quartz_slab"]}{"entrance":[19,1,7],"rooms":[{"name":"gallery","box":[16,2,10,22,4,10]},{"name":"kitchen","box":[11,2,9,15,4,13]},{"name":"dining","box":[11,2,14,15,4,18]},{"name":"living","box":[11,2,19,21,4,24]},{"name":"atrium","box":[17,1,12,21,4,17]},{"name":"corridor","box":[23,2,9,24,4,21]},{"name":"bedroom 1","box":[26,2,9,30,4,12]},{"name":"bath 1","box":[26,2,14,27,4,16]},{"name":"bath 2","box":[29,2,14,30,4,16]},{"name":"bedroom 2","box":[26,2,18,30,4,20]},{"name":"master bedroom","box":[23,2,22,30,4,24]}]}// Mid-century house generator: `node build.mjs [out.nbt]` (default build.nbt here). make.sh runs it and moves the result into place.
// Coordinates are plan.md's absolute ones. A structure grid is 0-based, so cells below y=0 (the bedding at y=-1 and the
// pool basin at y=-2..-1) cannot be stored: they are dropped and counted, and the pool reads as shallow water at y=0.
import { Grid, runParts } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import * as shell from "./parts/shell.mjs";
import * as site from "./parts/site.mjs";
import * as roofs from "./parts/roofs.mjs";
import * as facades from "./parts/facades.mjs";
import * as front from "./parts/front.mjs";
import * as back from "./parts/back.mjs";
import * as room1 from "./parts/room-1.mjs";
import * as room2 from "./parts/room-2.mjs";
import * as room3 from "./parts/room-3.mjs";
import * as room4 from "./parts/room-4.mjs";
import * as room5 from "./parts/room-5.mjs";
import * as room6 from "./parts/room-6.mjs";
import * as room7 from "./parts/room-7.mjs";
import * as room8 from "./parts/room-8.mjs";
import * as room9 from "./parts/room-9.mjs";
import * as room10 from "./parts/room-10.mjs";
import * as room11 from "./parts/room-11.mjs";
import { renameSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const out = process.argv[2] ?? join(here, "build.nbt");
const SIZE = [34, 9, 34]; // x 0..33, y 0..8 (chimney top), z 0..33

// kidney pool cells (plan.md RESERVED): no ground there, so the pool stays open
const POOL = { 29: [[14, 17], [20, 21]], 30: [[13, 22]], 31: [[13, 22]], 32: [[14, 21]] };
const inPool = (x, z) => (POOL[z] ?? []).some(([a, b]) => x >= a && x <= b);

const grid = new Grid(SIZE);
// the ground: dirt at y=0 over the lot except the pool (cells set here stay writable by every part, as sibling builds do)
for (let x = 0; x < SIZE[0]; x++) for (let z = 0; z < SIZE[2]; z++) if (!inPool(x, z)) grid.set(x, 0, z, "dirt");

// wrap the grid so writes below y=0 are dropped and counted instead of thrown
let dropped = 0;
const g = new Proxy(grid, {
  get(target, prop) {
    if (prop === "set") return (x, y, z, ...rest) => { if (y < 0) { dropped++; return g; } return target.set(x, y, z, ...rest); };
    const v = Reflect.get(target, prop);
    return typeof v === "function" ? v.bind(target) : v;
  },
});

const reports = runParts(g, [
  ["house shell and ground", shell.build],
  ["site, carport and paving", site.build],
  ["roofs, beams and fireplace stack", roofs.build],
  ["facades, glazing and entry", facades.build],
  ["car and front garden", front.build],
  ["pool, patio and garden details", back.build],
  ["room: gallery", room1.build],
  ["room: kitchen", room2.build],
  ["room: dining", room3.build],
  ["room: living", room4.build],
  ["room: atrium", room5.build],
  ["room: corridor", room6.build],
  ["room: bedroom 1", room7.build],
  ["room: bath 1", room8.build],
  ["room: bath 2", room9.build],
  ["room: bedroom 2", room10.build],
  ["room: master bedroom", room11.build],
], { palette: join(here, "palette.json") });
console.log(`cells below y=0 dropped (bedding and pool basin): ${dropped}`);
const tmp = out + ".tmp.nbt";
grid.save(tmp);
renameSync(tmp, out);
console.log(JSON.stringify({ saved: out, size: SIZE, parts: reports.map((r) => `${r.part}:${r.placed}${r.refused ? `(refused ${r.refused})` : ""}`) }));

